package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000000007

// Prime power dynamic programming state per prime
type PrimeDP struct {
	p       int64
	maxExp  int
	invCnt  []int // inv[e+1] mod MOD
	curr    []int // curr[e] = expected value of p^e after current step
}

// Returns a*b % MOD
func mul(a, b int) int {
	return int((int64(a) * int64(b)) % MOD)
}

// Modular exponentiation
func modpow(a int, e int64) int {
	res := 1
	base := a
	for e > 0 {
		if e&1 == 1 {
			res = mul(res, base)
		}
		base = mul(base, base)
		e >>= 1
	}
	return res
}

// Modular inverse using Fermat's little theorem
func modinv(a int) int {
	return modpow(a, MOD-2)
}

// Factorize n into prime powers: map[prime]exponent
func factorize(n int64) map[int64]int {
	factors := make(map[int64]int)
	// trial division up to n^(1/3) or so for speed; since n <= 1e15, sqrt(n) <= 3.2e7, feasible in Go with some optimizations
	// We'll use simple trial division up to n^0.5
	d := int64(2)
	for d*d <= n {
		for n%d == 0 {
			factors[d]++
			n /= d
		}
		d++
		if d > 2 && d%2 == 0 {
			d++
		}
	}
	if n > 1 {
		factors[n]++
	}
	return factors
}

func main() {
	reader := bufio.NewReader(os.Stdin)
	var n int64
	var k int
	if _, err := fmt.Fscan(reader, &n, &k); err != nil {
		return
	}

	factors := factorize(n)

	// For each prime, we will compute expected value after k steps.
	// The overall expected value is product over primes of expected value of p^e.
	// Initialize answer = 1
	ans := 1

	for p, emax := range factors {
		// Precompute inv[e+1] for e=0..emax
		invCnt := make([]int, emax+1)
		for e := 0; e <= emax; e++ {
			invCnt[e] = modinv(e + 1)
		}
		// curr[e] = expected value of p^e after current step
		curr := make([]int, emax+1)
		// step 0: curr[e] = p^e mod MOD
		pe := 1
		for e := 0; e <= emax; e++ {
			curr[e] = pe
			pe = mul(pe, int(p%MOD))
		}
		// Perform k steps
		for step := 0; step < k; step++ {
			// compute prefix sums of curr
			prefix := make([]int, emax+1)
			sum := 0
			for e := 0; e <= emax; e++ {
				sum += curr[e]
				if sum >= MOD {
					sum -= MOD
				}
				prefix[e] = sum
			}
			// new_curr[e] = prefix[e] * inv[e+1] mod MOD
			for e := 0; e <= emax; e++ {
				curr[e] = mul(prefix[e], invCnt[e])
			}
		}
		// Multiply ans by curr[emax] (expected value for this prime with initial exponent emax)
		ans = mul(ans, curr[emax])
	}

	fmt.Println(ans)
}
